            command: 'pnpm --filter @cipherbox/web dev',
            url: 'http://localhost:5173',
            reuseExistingServer: !process.env.CI,
            timeout: 120000,
            cwd: resolve(__dirname, '../..'),
          },
        ],
      }),
});

